head.script:
scwin.onpageload = function() {
    window.temp = 0;
    localStorage.removeItem("log");
    ica_inputCalendar1.setValue("20201223");
};
scwin.onpageunload = function() {};
scwin.dateValidator = function(value, comObj) {
    console.log("scwin.dateValidator");
    var temp2 = temp++;
    localStorage.setItem("log", temp2);
    console.log(1111 + " - > " + temp2);
    return value;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
    scwin.simulateWrapper('#ica_inputCalendar1_input', 'key-combo', {
        combo: 'TAB'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ica_inputCalendar1_input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ica_inputCalendar1_input').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ica_inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 1", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
